import React from 'react';
import Schedule from './index';

declare namespace ScheduleReact {
    /**
     * React-idiomatic camelCase aliases for the lemonadejs callbacks. The
     * wrapper drops the leading `self` argument before invoking these — the
     * instance is available via the forwarded ref.
     *
     * The lowercase names from `Schedule.Options` (e.g. `oncreate`) still
     * work for legacy compatibility, but new code should prefer these.
     */
    interface ReactCallbacks {
        /** Before events are added. Always called with an array (length >= 1). Return `false` to cancel. */
        onBeforeCreate?: (events: Schedule.Event[], e?: MouseEvent) => boolean | void;
        /** Fired after events are added. Always called with an array (length >= 1). */
        onCreate?: (events: Schedule.Event[], e?: MouseEvent) => void;
        /** Per-event hook during the drag-to-create gesture. Return a modified event, or `false` to drop it. */
        onBeforeInsert?: (event: Schedule.Event) => Schedule.Event | boolean | void;
        /** Fired after creating an event interactively, and on double-click of an event. */
        onEdition?: (event: Schedule.Event) => void;
        /** Fired on double-click of an event. */
        onDblClick?: (event: Schedule.Event) => void;
        /** Fired for each event removed via `deleteEvents` or the Delete key. */
        onDelete?: (event: Schedule.Event) => void;
        /** Before a drag/resize change is applied. Return `false` to cancel. */
        onBeforeChangeEvent?: (state: object) => boolean | void;
        /** Fired after `updateEvent` applies changes. */
        onChangeEvent?: (event: Schedule.Event, oldValue: Partial<Schedule.Event>, newValue: Partial<Schedule.Event>) => void;
        /** Before `updateEvent` / `deleteEvents` / `setData`. Return `false` to cancel. */
        onBeforeChange?: (state: { action: 'updateEvent' | 'deleteEvents' | 'setData'; [key: string]: any }) => boolean | void;
        /** Fired after `updateEvent` / `deleteEvents` / `setData` and after an interactive create. */
        onChange?: () => void;
        /** Fired on validation errors. */
        onError?: (message: string) => void;
    }

    /** Wrapper-only props (the wrapping `<div>` accepts these). */
    interface DOMProps {
        className?: string;
        style?: React.CSSProperties;
        children?: React.ReactNode;
    }

    /**
     * Re-export the underlying type namespace so consumers writing
     *   import { Schedule } from '@lemonadejs/schedule/react';
     *   import type { Schedule as ScheduleNS } from '@lemonadejs/schedule/react';
     * get `ScheduleNS.Event`, `ScheduleNS.EventInput`, `ScheduleNS.Options`,
     * `ScheduleNS.Instance` directly off the React import. Same for the
     * `@calendarjs/react` aggregate that re-exports this default.
     */
    export type Event = Schedule.Event;
    export type EventInput = Schedule.EventInput;
    export type Options = Schedule.Options;
    export type Instance = Schedule.Instance;
}

// Use `interface` (not `const`) so the value type can declaration-merge with
// the same-named `namespace` above. That merge is what carries the type
// members (`Event`, `EventInput`, ...) along with the React component value
// when the default export is re-exported elsewhere.
interface ScheduleReact extends React.MemoExoticComponent<
    React.ForwardRefExoticComponent<
        Omit<Schedule.Options,
            | 'onbeforecreate' | 'oncreate' | 'onbeforeinsert' | 'onedition' | 'ondblclick'
            | 'ondelete' | 'onbeforechangeevent' | 'onchangeevent' | 'onbeforechange'
            | 'onchange' | 'onerror'>
        & ScheduleReact.ReactCallbacks
        & ScheduleReact.DOMProps
        & React.RefAttributes<Schedule.Instance>
    >
> {}

declare const ScheduleReact: ScheduleReact;

export default ScheduleReact;
